  return <PublicCollection label={t("Events / Host", "الفعاليات / استضف")} title={t("Bring a useful conversation together.", "اجمع محادثة مفيدة معا.")} copy={t("ASaaSI features community-hosted events that give founders a clear outcome, not just an audience.", "يعرض أساسي فعاليات يستضيفها المجتمع وتمنح المؤسسين نتيجة واضحة، لا جمهورا فقط.")} aside={<div className="hero-aside-note"><span className="mono">{t("Time to complete", "الوقت المطلوب")}</span><strong>3 {t("minutes", "دقائق")}</strong><p>{t("We review every submission before it goes on the calendar.", "نراجع كل طلب قبل إضافته إلى التقويم.")}</p></div>}>{sent ? <div className="success-state public-success" role="status" aria-live="polite"><div className="complete-node"><Check size={22} /></div><SectionLabel>{t("Event submitted", "تم إرسال الفعالية")}</SectionLabel><h2>{t("We'll review it and follow up within a few days.", "سنراجعها ونتابع خلال أيام قليلة.")}</h2><p>{t("If it's a fit, we'll help you list it on the calendar with registration built in.", "إذا كانت مناسبة، سنساعدك على إدراجها في التقويم مع تسجيل جاهز.")}</p><Link href="/events" className="button button-dark">{t("Back to events", "العودة إلى الفعاليات")} <ArrowRight size={14} /></Link></div> : <><RelationshipThread labels={[t("Brief", "الموجز"), t("Review", "المراجعة"), t("Listed", "مُدرَجة")]} ariaLabel={t("How an event submission is reviewed", "كيف تُراجَع الفعالية المُرسَلة")} /><form className="application-form" onSubmit={(event) => { event.preventDefault(); setSent(true); }}><div className="form-grid-two"><label htmlFor="host-title">{t("Event title", "عنوان الفعالية")}<input id="host-title" required placeholder={t("Give it a clear name", "اعطها اسما واضحا")} /></label><label htmlFor="host-email">{t("Your email", "بريدك الإلكتروني")}<input id="host-email" type="email" required placeholder="you@company.com" /></label></div><div className="form-grid-two"><label htmlFor="host-format">{t("Format", "الصيغة")}<select id="host-format" required defaultValue=""><option value="" disabled>{t("Select a format", "اختر صيغة")}</option><option>{t("In person", "حضوري")}</option><option>{t("Online", "عبر الإنترنت")}</option><option>{t("Hybrid", "مختلط")}</option></select></label><label htmlFor="host-city">{t("City", "المدينة")}<input id="host-city" placeholder={t("Dubai, Cairo, Riyadh...", "دبي، القاهرة، الرياض...")} /></label></div><label htmlFor="host-outcome">{t("What will attendees leave with?", "بماذا سيغادر الحضور؟")}<textarea id="host-outcome" required placeholder={t("One clear outcome, not a general topic.", "نتيجة واضحة واحدة، لا موضوعا عاما.")} /></label><div className="form-footer"><span className="mono">{t("Free to submit", "الإرسال مجاني")}</span><button className="button button-primary" type="submit">{t("Submit event", "أرسل الفعالية")} <ArrowRight size={14} /></button></div></form></>}</PublicCollection>;
