export function WebinarsPage() {
  const { t, formatNum } = useLocale();
  const upcoming = webinars.filter((webinar) => !webinar.past);
  const past = webinars.filter((webinar) => webinar.past);
  const liveMap = <div className="webinar-live-map"><span className="mono">{t("Live-room path", "مسار الغرفة المباشرة")}</span><strong>{t("Date → live room → field note", "التاريخ ← الغرفة المباشرة ← الملاحظة الميدانية")}</strong><ol><li>{t("Choose the working question", "اختر سؤال العمل")}</li><li>{t("Join the operator room", "انضم لغرفة المشغل")}</li><li>{t("Keep the useful note", "احتفظ بالملاحظة المفيدة")}</li></ol></div>;
  return <><PageIntro label={t("Learn / Webinars", "تعلم / ندوات")} title={t("Live sessions with real time to ask questions.", "جلسات مباشرة مع وقت حقيقي لطرح الأسئلة.")} copy={t("Short, practical webinars with the operators who've actually done the thing, not a recorded pitch.", "ندوات مباشرة قصيرة وعملية مع مشغلين فعلوا الأمر فعلا، لا عرضا مسجلا.")} note={liveMap} /><section className="section"><div className="container"><div className="section-header"><div><SectionLabel>{t("Upcoming live rooms", "الغرف المباشرة القادمة")}</SectionLabel><h2>{t(`${upcoming.length} dates to choose from`, `${formatNum(upcoming.length)} مواعيد للاختيار منها`)}</h2></div><Link href="/learn" className="text-link">{t("Browse all learning content", "تصفح كل محتوى التعلم")} <ArrowRight size={14} /></Link></div><div className="webinar-timeline" aria-label={t("Upcoming webinar timeline", "الخط الزمني للندوات القادمة")}>{upcoming.map((webinar, index) => <Link href={`/webinars/${webinar.slug}`} key={webinar.slug} className="webinar-timeline-row"><div className="webinar-date"><span>{String(index + 1).padStart(2, "0")}</span><strong>{t(webinar.date, webinar.dateAr)}</strong></div><div className="webinar-timeline-copy"><SignalTag tone="soft">{t("Live room · 45 min", "غرفة مباشرة · ٤٥ دقيقة")}</SignalTag><h3>{t(webinar.title, webinar.titleAr)}</h3><p>{t(webinar.copy, webinar.copyAr)}</p></div><ArrowRight size={17} aria-hidden="true" /></Link>)}</div></div></section><section className="section webinar-replay-section"><div className="container"><div className="section-header"><div><SectionLabel>{t("Replay evidence", "دليل التسجيلات")}</SectionLabel><h2>{t("Field notes from rooms already held.", "ملاحظات ميدانية من غرف انعقدت بالفعل.")}</h2></div></div><div className="past-events-list">{past.map((webinar) => <Link href={`/webinars/${webinar.slug}`} key={webinar.slug} className="past-event-row webinar-past-row"><SignalTag tone="soft">{t("Replay", "تسجيل")}</SignalTag><div><strong>{t(webinar.title, webinar.titleAr)}</strong><span>{t(webinar.date, webinar.dateAr)} · {t(webinar.copy, webinar.copyAr)}</span></div><ArrowRight size={16} /></Link>)}</div></div></section></>;
}

export function WorkspaceDirectoryPage({ professionals = false }: { professionals?: boolean }) {
  const { t, formatNum, isRTL } = useLocale();
  const [query, setQuery] = useState("");
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [stage, setStage] = useState("All stages");
  const [city, setCity] = useState("All cities");
  const [availability, setAvailability] = useState("Any availability");
  const [saved, setSaved] = useState<string[]>([]);
  const [relevanceFeedback, setRelevanceFeedback] = useState(() => getRecommendationFeedback());
  const [feedbackTarget, setFeedbackTarget] = useState<string | null>(null);
  const [recoveryOpen, setRecoveryOpen] = useState(false);
  const searchParams = typeof window === "undefined" ? new URLSearchParams() : new URLSearchParams(window.location.search);
  const requestedIntent = searchParams.get("intent") ?? "";
  const requestedDecisionId = searchParams.get("decision") ?? "";
  const outcomeDecision = requestedDecisionId ? getWorkflowRecords().find((record) => record.id === requestedDecisionId && record.kind === "decision" && Boolean(record.outcome)) : undefined;
  const outcomeEvidence = outcomeDecision ? (outcomeDecision.evidence || outcomeDecision.weeklyReflection || outcomeDecision.nextAction || "") : "";
  const outcomeWords = `${outcomeDecision?.title ?? ""} ${outcomeEvidence}`.toLowerCase();
  useEffect(() => {
    if (!outcomeDecision || typeof window === "undefined") return;
    const retainOutcomeContext = (event: MouseEvent) => {
      const target = event.target instanceof Element ? event.target.closest<HTMLAnchorElement>(".workspace-person-card a[href^='/dashboard/members/']") : null;
      if (target) window.localStorage.setItem("asaasi-matching-decision", outcomeDecision.id);
    };
    document.addEventListener("click", retainOutcomeContext);
    return () => document.removeEventListener("click", retainOutcomeContext);
  }, [outcomeDecision?.id]);
  const founderContext = getFounderContext();
  const contextStatus = getFounderContextStatus(founderContext);
  const founderStage = founderContext?.stage === "Idea" ? "Validate" : founderContext?.stage === "First revenue" ? "Build" : founderContext?.stage === "Growth" ? "Scale" : undefined;
  const founderCity = founderContext?.market === "Egypt" ? "Cairo" : founderContext?.market === "GCC" ? "Dubai" : founderContext?.market === "Levant" ? "Amman" : undefined;
  const stageLabel = founderContext?.stage === "Idea" ? t("Idea / validation", "فكرة / تحقق") : founderContext?.stage === "First revenue" ? t("First revenue", "أول إيراد") : founderContext?.stage === "Growth" ? t("Growth motion", "حركة نمو") : "";
  const marketLabel = founderContext?.market === "Egypt" ? t("Egypt", "مصر") : founderContext?.market === "GCC" ? t("GCC", "الخليج") : founderContext?.market === "Levant" ? t("Levant", "المشرق") : founderContext?.market === "Multiple MENA markets" ? t("Multiple MENA markets", "أسواق متعددة في المنطقة") : "";
  const contextWords = `${founderContext?.signal ?? ""} ${founderContext?.operatingContext ?? ""} ${founderContext?.interests.join(" ") ?? ""}`.toLowerCase();
  const matchReasons = (person: typeof people[number]) => {
    const reasons: string[] = [];
    if (founderStage === person.stage) reasons.push(t("same operating stage", "المرحلة التشغيلية نفسها"));
    if (founderCity === person.city) reasons.push(t("near your market", "قريب من سوقك"));
    if (/pricing|price|تسعير/.test(contextWords) && /pricing/.test(`${person.role} ${person.focus}`.toLowerCase())) reasons.push(t("pricing context", "سياق التسعير"));
    if (/customer|discovery|enterprise|growth|عميل|اكتشاف|مؤسسي|نمو/.test(contextWords) && /growth|enterprise|product/.test(`${person.role} ${person.focus}`.toLowerCase())) reasons.push(t("current operating focus", "التركيز التشغيلي الحالي"));
    if (requestedIntent === "next-step" && person.availability === "Available this month") reasons.push(t("available for a near-term next step", "متاح لخطوة تالية قريبة"));
    if (outcomeDecision && /pricing|price|تسعير/.test(outcomeWords) && /pricing/.test(`${person.role} ${person.focus}`.toLowerCase())) reasons.push(t("relevant to retained decision learning", "مناسب لتعلم القرار المحتفظ به"));
    if (outcomeDecision && /customer|discovery|enterprise|growth|عميل|اكتشاف|مؤسسي|نمو/.test(outcomeWords) && /growth|enterprise|product/.test(`${person.role} ${person.focus}`.toLowerCase())) reasons.push(t("relevant to retained decision learning", "مناسب لتعلم القرار المحتفظ به"));
    return reasons;
  };
  const filtered = useMemo(() => people.filter((person) => !relevanceFeedback[person.name] && `${person.name} ${person.role} ${person.city} ${person.focus}`.toLowerCase().includes(query.toLowerCase()) && (stage === "All stages" || person.stage === stage) && (city === "All cities" || person.city === city) && (availability === "Any availability" || person.availability === availability)).sort((a, b) => matchReasons(b).length - matchReasons(a).length), [availability, city, query, stage, contextWords, founderCity, founderStage, outcomeWords, requestedIntent, relevanceFeedback]);
  const toggleSaved = (name: string) => setSaved((current) => current.includes(name) ? current.filter((item) => item !== name) : [...current, name]);
  const markNotRelevant = (name: string, reason: RecommendationFeedbackReason) => { setRelevanceFeedback((current) => setRecommendationFeedback(current, name, reason)); setFeedbackTarget(null); };
  const restoreRecommendation = (name: string) => setRelevanceFeedback((current) => removeRecommendationFeedback(current, name));
  const activeFilterCount = Number(stage !== "All stages") + Number(city !== "All cities") + Number(availability !== "Any availability");
  const contextReady = Boolean(founderContext) && contextStatus.complete === contextStatus.total;
  const contextSummary = founderContext ? t(`Results consider your ${stageLabel} stage, ${marketLabel} market, operating interests, and current work. Every recommendation keeps the reason visible.`, `تأخذ النتائج في الاعتبار مرحلة ${stageLabel} وسوق ${marketLabel} واهتماماتك التشغيلية وعملك الحالي. يبقى سبب كل توصية ظاهرا.`) : "";
  const dismissed = people.filter((person) => relevanceFeedback[person.name]);
  const feedbackOptions: { value: RecommendationFeedbackReason; en: string; ar: string }[] = [{ value: "stage", en: "Different stage", ar: "مرحلة مختلفة" }, { value: "market", en: "Different market", ar: "سوق مختلف" }, { value: "focus", en: "Different problem", ar: "مشكلة مختلفة" }, { value: "timing", en: "Not the right time", ar: "ليس الوقت مناسبا" }, { value: "other", en: "Other", ar: "سبب آخر" }];
  const feedbackReasonLabel = (reason: RecommendationFeedbackReason) => feedbackOptions.find((option) => option.value === reason) ?? feedbackOptions[4];
  return <ProductShell title={professionals ? t("Professionals", "المحترفون") : t("Network", "شبكتك")} active={professionals ? "/dashboard/professionals" : "/dashboard/network"}><div className="workspace-route-page"><div className="product-page-heading compact"><div><SectionLabel>{professionals ? t("Workspace / Professionals", "مساحة العمل / المحترفون") : t("Workspace / Network", "مساحة العمل / شبكتك")}</SectionLabel><h1>{professionals ? t("Find the operator for the work in front of you.", "اعثر على المشغل المناسب للعمل أمامك.") : t("Your network, narrowed to what matters.", "شبكتك، مركزة على ما يهم.")}</h1><p>{t("Use the signal, stage, city, and availability filters to make the next introduction intentional.", "استخدم فلاتر الإشارة والمرحلة والمدينة والتوفر لجعل المقدمة التالية مقصودة.")}</p></div><Link href="/matching" className="button button-primary">{t("Open matching", "فتح المطابقة")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</Link></div><section className={`workspace-context-match ${contextReady ? "is-ready" : ""}`}><div><SectionLabel>{t("Founder-context matching", "مطابقة سياق المؤسس")}</SectionLabel><h2>{contextReady ? t("The directory is ordered by your operating context.", "يُرتب الدليل وفق سياقك التشغيلي.") : t("Give the directory the context behind your request.", "امنح الدليل السياق وراء طلبك.")}</h2><p>{contextReady ? contextSummary : t("Complete founder context first, then use the visible reason on every record to decide whether an introduction is worth asking for.", "أكمل سياق المؤسس أولا، ثم استخدم السبب الظاهر في كل سجل لتقرر ما إذا كانت المقدمة تستحق الطلب.")}</p></div>{contextReady ? <span className="workspace-context-match__metric">{formatNum(filtered.filter((person) => matchReasons(person).length > 0).length)} {t("explained matches", "مطابقات مفسرة")}</span> : <Link href="/dashboard/profile" className="button button-light">{t("Complete context", "أكمل السياق")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</Link>}</section>{outcomeDecision && <section className="workspace-outcome-match"><div><SectionLabel>{t("Decision evidence", "دليل القرار")}</SectionLabel><h2>{t("Bring the retained learning into the next right conversation.", "أحضر التعلم المحتفظ به إلى المحادثة المناسبة التالية.")}</h2><p>{t("This shortlist is ordered with one completed decision in view. Each relevant reason names the learning connection, so the introduction begins from evidence rather than a generic ask.", "تُرتب هذه القائمة المختصرة مع قرار مكتمل واحد في الاعتبار. يسمي كل سبب ذي صلة رابط التعلم، لتبدأ المقدمة من دليل لا من طلب عام.")}</p></div><article><span>{outcomeDecision.outcome === "keep" ? t("Keep direction", "أبقِ الاتجاه") : outcomeDecision.outcome === "change" ? t("Change approach", "غيّر النهج") : t("Stop bet", "أوقف الرهان")}</span><strong>{t(outcomeDecision.title, outcomeDecision.titleAr)}</strong><p>{outcomeEvidence || t("The retained outcome is ready to provide context for the next question.", "النتيجة المحتفظ بها جاهزة لتوفير سياق للسؤال التالي.")}</p><Link href="/dashboard/decision-review" className="text-link">{t("Reopen decision learning", "أعد فتح تعلم القرار")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link></article></section>}{dismissed.length > 0 && <section className="workspace-feedback-recovery"><div><SectionLabel>{t("Match feedback", "ملاحظات المطابقة")}</SectionLabel><h2>{t(`${formatNum(dismissed.length)} recommendation${dismissed.length === 1 ? "" : "s"} paused`, `${formatNum(dismissed.length)} توصية متوقفة`)}</h2><p>{t("Your feedback is shaping the active shortlist. Restore a recommendation whenever the operating context changes.", "تشكل ملاحظاتك القائمة المختصرة النشطة. أعد أي توصية عندما يتغير السياق التشغيلي.")}</p></div><button type="button" className="button button-light" aria-expanded={recoveryOpen} onClick={() => setRecoveryOpen((current) => !current)}>{recoveryOpen ? t("Close recovery", "إغلاق الاستعادة") : t("Review dismissed", "راجع المستبعد")}</button>{recoveryOpen && <div className="workspace-feedback-recovery__list">{dismissed.map((person) => { const feedback = relevanceFeedback[person.name]; const reason = feedbackReasonLabel(feedback.reason); return <article key={person.name}><div><strong>{person.name}</strong><span>{t(reason.en, reason.ar)}</span></div><button type="button" className="text-link" onClick={() => restoreRecommendation(person.name)}>{t("Restore", "استعادة")}</button></article>; })}</div>}</section>}<div className="workspace-filter-strip"><div className="search-field"><Search size={16} aria-hidden="true" /><label className="sr-only" htmlFor="workspace-network-search">{t("Search the network", "ابحث في الشبكة")}</label><input id="workspace-network-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t("Search the network", "ابحث في الشبكة")} /></div><button type="button" className={`filter-button ${filtersOpen ? "active" : ""}`} aria-expanded={filtersOpen} aria-controls="workspace-directory-filters" onClick={() => setFiltersOpen((open) => !open)}><Filter size={15} aria-hidden="true" /> {t("Filters", "الفلاتر")} {activeFilterCount ? <span>{formatNum(activeFilterCount)}</span> : null}</button><SignalTag tone="soft">{formatNum(filtered.length)} {t("relevant", "ذات صلة")}</SignalTag></div>{filtersOpen && <section id="workspace-directory-filters" className="workspace-filter-panel" aria-label={t("Directory filters", "فلاتر الدليل")}><label>{t("Founder stage", "مرحلة المؤسس")}<select value={stage} onChange={(event) => setStage(event.target.value)}><option value="All stages">{t("All stages", "كل المراحل")}</option><option value="Validate">{t("Validate", "تحقق")}</option><option value="Build">{t("Build", "بناء")}</option><option value="Scale">{t("Scale", "توسع")}</option></select></label><label>{t("City", "المدينة")}<select value={city} onChange={(event) => setCity(event.target.value)}><option value="All cities">{t("All cities", "كل المدن")}</option><option value="Amman">{t("Amman", "عمان")}</option><option value="Dubai">{t("Dubai", "دبي")}</option><option value="Cairo">{t("Cairo", "القاهرة")}</option></select></label><label>{t("Availability", "التوفر")}<select value={availability} onChange={(event) => setAvailability(event.target.value)}><option value="Any availability">{t("Any availability", "أي توفر")}</option><option value="Available this month">{t("Available this month", "متاح هذا الشهر")}</option><option value="Limited availability">{t("Limited availability", "توفر محدود")}</option></select></label><button type="button" className="text-link" onClick={() => { setQuery(""); setStage("All stages"); setCity("All cities"); setAvailability("Any availability"); }}>{t("Clear filters", "مسح الفلاتر")} <X size={14} /></button></section>}{filtered.length ? <div className="workspace-directory-grid">{filtered.map((person) => { const index = people.findIndex((candidate) => candidate.name === person.name); const reasons = matchReasons(person); return <article className="workspace-person-card" key={person.name}><div className={`directory-avatar directory-avatar-${index + 1}`}>{person.name.split(" ").map((part) => part[0]).join("")}</div><SectionLabel>{reasons.length ? t("Context fit", "ملاءمة للسياق") : t("In your orbit", "ضمن دائرتك")}</SectionLabel><h2>{person.name}</h2><p>{t(person.role, person.roleAr)} · {t(person.city, person.cityAr)}</p><span>{t(person.focus, person.focusAr)} · {t(person.availability, person.availabilityAr)}</span>{reasons.length > 0 && <div className="workspace-person-card__reason"><p><strong>{t("Why this fit:", "سبب الملاءمة:")}</strong> {reasons.join(t(" · ", " · "))}</p>{feedbackTarget === person.name ? <div className="workspace-person-card__feedback" role="group" aria-label={t("Why is this recommendation not relevant?", "لماذا هذه التوصية غير مناسبة؟")}>{feedbackOptions.map((option) => <button type="button" key={option.value} onClick={() => markNotRelevant(person.name, option.value)}>{t(option.en, option.ar)}</button>)}<button type="button" className="text-link" onClick={() => setFeedbackTarget(null)}>{t("Cancel", "إلغاء")}</button></div> : <button type="button" onClick={() => setFeedbackTarget(person.name)}>{t("Not relevant", "غير مناسب")}</button>}</div>}<div><Link href={`/dashboard/members/${index + 1}`} className="text-link">{t("Open profile", "فتح الملف")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</Link><button type="button" className={`icon-button ${saved.includes(person.name) ? "is-saved" : ""}`} aria-label={`${saved.includes(person.name) ? t("Remove", "إزالة") : t("Save", "حفظ")} ${person.name}`} aria-pressed={saved.includes(person.name)} onClick={() => toggleSaved(person.name)}><Bookmark size={15} /></button></div>{saved.includes(person.name) && <span className="action-feedback" role="status"><Check size={13} /> {t("Saved to your shortlist", "حُفظ في قائمتك المختصرة")}</span>}</article>; })}</div> : <div className="empty-state"><h2>{t("No people match that search.", "لا يطابق بحثك أي أشخاص.")}</h2><p>{dismissed.length ? t("Restore a paused recommendation or clear a filter to bring another useful starting point back.", "استعد توصية متوقفة أو امسح فلترًا لإعادة نقطة بداية مفيدة.") : t("Try a broader role, city, availability, or problem.", "جرب دورا أو مدينة أو توفرا أو مشكلة أوسع.")}</p><button type="button" className="button button-dark" onClick={() => { setQuery(""); setStage("All stages"); setCity("All cities"); setAvailability("Any availability"); }}>{t("Clear search and filters", "مسح البحث والفلاتر")}</button></div>}</div></ProductShell>;
}

export function MemberProfilePage({ workspace = false }: { workspace?: boolean }) {
  const { t, isRTL } = useLocale();
  const [, params] = useRoute(workspace ? "/dashboard/members/:id" : "/members/:id");
  const profileId = Number(params?.id ?? "1");
  const person = people[(profileId - 1 + people.length) % people.length];
  const { isAuthed } = useAuth();
  const isMember = workspace || isAuthed;
  const [introRequested, setIntroRequested] = useState(false);
  const [introDraftOpen, setIntroDraftOpen] = useState(false);
  const [introQuestion, setIntroQuestion] = useState("");
  const decisionOptions = getWorkflowRecords().filter((record) => record.kind === "decision");
  const matchedDecisionId = typeof window === "undefined" ? "" : window.localStorage.getItem("asaasi-matching-decision") ?? "";
  const matchedDecision = decisionOptions.find((record) => record.id === matchedDecisionId && Boolean(record.outcome));
  const [linkedDecisionId, setLinkedDecisionId] = useState(() => matchedDecision?.id ?? "");
  const reusableIntroductionOutcome = getWorkflowRecords().find((record) => record.kind === "introduction" && record.outcomeCheckCompletedAt && record.introductionOutcomeNote);
  const [subscriber] = useState(() => typeof window !== "undefined" && window.localStorage.getItem("asaasi-access-tier") === "subscriber");
  const [introUsed, setIntroUsed] = useState(() => typeof window !== "undefined" && window.localStorage.getItem("asaasi-intro-used") === "true");
  const introCapped = !subscriber && introUsed && !introRequested;
  const introductionQualityReady = introQuestion.trim().length >= 24 && (decisionOptions.length === 0 || Boolean(linkedDecisionId));
  useEffect(() => {
    if (!introDraftOpen || introQuestion.trim() || !matchedDecision) return;
    const evidence = matchedDecision.evidence || matchedDecision.weeklyReflection || matchedDecision.nextAction || t("the retained learning from this decision", "التعلم المحتفظ به من هذا القرار");
    const outcome = matchedDecision.outcome === "keep" ? t("keep", "الاستمرار") : matchedDecision.outcome === "change" ? t("change", "التغيير") : t("stop", "الإيقاف");
    setIntroQuestion(t(`I am revisiting “${matchedDecision.title}” after a ${outcome} outcome. The evidence I am carrying is: ${evidence}. Given your experience with ${person.focus}, what would you test next?`, `أعيد النظر في «${matchedDecision.titleAr}» بعد نتيجة ${outcome}. الدليل الذي أحمله هو: ${evidence}. وبالنظر إلى خبرتك في ${person.focusAr}، ما الذي ستختبره بعد ذلك؟`));
  }, [introDraftOpen, introQuestion, matchedDecision, person.focus, person.focusAr, t]);
  useEffect(() => {
    if (!introDraftOpen || typeof document === "undefined") return;
    const question = document.querySelector<HTMLTextAreaElement>(".intro-request-draft textarea");
    const decision = document.querySelector<HTMLSelectElement>(".intro-request-draft select");
    if (question) question.setCustomValidity(introQuestion.trim().length > 0 && introQuestion.trim().length < 24 ? t("Write a little more context so the member can give a useful answer.", "اكتب مزيدا من السياق كي يتمكن العضو من تقديم إجابة مفيدة.") : "");
    if (decision) decision.setCustomValidity(decisionOptions.length > 0 && !linkedDecisionId ? t("Link the introduction to the decision it should help change.", "اربط المقدمة بالقرار الذي ينبغي أن تساعد في تغييره.") : "");
  }, [decisionOptions.length, introDraftOpen, introQuestion, isRTL, linkedDecisionId, t]);
  const submitIntroduction = (event: FormEvent) => { event.preventDefault(); if (!introductionQualityReady) return; const carryForward = reusableIntroductionOutcome?.introductionOutcomeNote ? `\n\n${t("Relevant prior introduction learning", "تعلم سابق ذو صلة من مقدمة")}: ${reusableIntroductionOutcome.introductionOutcomeNote}` : ""; setIntroRequested(true); setIntroDraftOpen(false); upsertWorkflowRecord({ id: `introduction-${person.name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`, kind: "introduction", title: `Introduction: ${person.name}`, titleAr: `مقدمة: ${person.name}`, href: workspace ? `/dashboard/members/${profileId}` : `/members/${profileId}`, status: "submitted", owner: "ASaaSI", ownerAr: "أساسي", nextAction: "Wait for the member introduction and keep the first conversation focused", nextActionAr: "انتظر مقدمة العضو وحافظ على تركيز المحادثة الأولى", evidence: `${introQuestion.trim()}${carryForward}`, linkedDecisionId: linkedDecisionId || undefined }); if (!subscriber) { window.localStorage.setItem("asaasi-intro-used", "true"); setIntroUsed(true); } };
  const body = <div className="member-profile"><article className="member-profile-main"><div className="member-profile-heading"><div className={`directory-avatar directory-avatar-${((profileId - 1) % people.length) + 1}`}>{person.name.split(" ").map((part) => part[0]).join("")}</div><div><SignalTag tone="soft">{t("Verified member", "عضو موثق")}</SignalTag><h1>{person.name}</h1><p>{t(person.role, person.roleAr)} · {t(person.city, person.cityAr)} · {t(person.stage, person.stage === "Scale" ? "توسع" : person.stage === "Build" ? "بناء" : "تحقق")} {t("stage", "مرحلة")}</p></div></div><div className="member-profile-meta"><span>{t(person.focus, person.focusAr)}</span><span>{t(person.availability, person.availabilityAr)}</span><span>{t("Member since 2024", "عضو منذ ٢٠٢٤")}</span></div><section><SectionLabel>{t("Current focus", "التركيز الحالي")}</SectionLabel><h2>{t("Working on the decision behind the next move.", "يعمل على القرار الذي يسبق الخطوة التالية.")}</h2><p>{t(person.experience, person.experienceAr)}</p></section><section><SectionLabel>{t("Experience signals", "إشارات الخبرة")}</SectionLabel><div className="member-experience-grid"><div><span className="mono">{t("BEST FOR", "مناسب لـ")}</span><strong>{t(person.focus, person.focusAr)}</strong></div><div><span className="mono">{t("STAGE CONTEXT", "سياق المرحلة")}</span><strong>{t(person.stage, person.stage === "Scale" ? "توسع" : person.stage === "Build" ? "بناء" : "تحقق")} {t("teams", "فرق")}</strong></div><div><span className="mono">{t("INTRO FORMAT", "صيغة المقدمة")}</span><strong>{t("One focused question", "سؤال مركز واحد")}</strong></div></div></section></article><aside className="member-profile-aside"><SignalTag tone="soft">{t("Why this profile surfaced", "سبب ظهور هذا الملف")}</SignalTag><strong>{t("Matches the current decision in your founder brief.", "يتطابق مع القرار الحالي في موجز مؤسسك.")}</strong><p>{t("ASaaSI keeps the reason visible before you ask for someone’s time.", "يبقي أساسي السبب واضحا قبل أن تطلب وقت أحد.")}</p>{isMember ? (introCapped ? <><div className="empty-state" style={{ padding: 20 }}><LockKeyhole size={18} /><h2>{t("Free tier limit reached.", "وصلت إلى حد الفئة المجانية.")}</h2><p>{t("Free members get one introduction request. Member access is unlimited.", "يحصل الأعضاء المجانيون على طلب مقدمة واحد. وصول الأعضاء غير محدود.")}</p><Link href="/dashboard/billing" className="button button-dark">{t("Upgrade to Member", "الترقية إلى عضو")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</Link></div></> : <>{introRequested ? <div className="intro-request-success" role="status"><Check size={16} /><strong>{t("Introduction brief sent", "تم إرسال موجز المقدمة")}</strong><p>{t("The request is now in Activity with its decision link. Keep the first conversation focused on the question you named.", "الطلب موجود الآن في النشاط مع رابط القرار. حافظ على تركيز المحادثة الأولى على السؤال الذي سميته.")}</p><Link href="/dashboard/registrations" className="text-link">{t("Open Activity", "افتح النشاط")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link></div> : introDraftOpen ? <form className="intro-request-draft" onSubmit={submitIntroduction}><label>{t("What is the one question this introduction should help answer?", "ما السؤال الواحد الذي ينبغي أن تساعد هذه المقدمة في الإجابة عنه؟")}<textarea value={introQuestion} onChange={(event) => setIntroQuestion(event.target.value)} placeholder={t(`For ${person.name}: I am deciding...`, `بالنسبة إلى ${person.name}: أقرر الآن...`)} required /></label>{decisionOptions.length > 0 && <label className="intro-request-draft__decision">{t("Connect this introduction to a saved decision", "اربط هذه المقدمة بقرار محفوظ")}<select value={linkedDecisionId} onChange={(event) => setLinkedDecisionId(event.target.value)}><option value="">{t("No linked decision", "لا يوجد قرار مرتبط")}</option>{decisionOptions.map((decision) => <option key={decision.id} value={decision.id}>{t(decision.title, decision.titleAr)}</option>)}</select></label>}<p>{t("A useful request names the decision, the constraint, and the specific input you need. The brief is saved to your workspace when sent.", "يسمي الطلب المفيد القرار والقيد والمدخل المحدد الذي تحتاجه. يُحفظ الموجز في مساحة عملك عند الإرسال.")}</p><div><button type="submit" className="button button-primary"><Check size={14} /> {t("Send introduction brief", "أرسل موجز المقدمة")}</button><button type="button" className="text-link" onClick={() => setIntroDraftOpen(false)}>{t("Cancel", "إلغاء")}</button></div></form> : <><button type="button" className="button button-primary" onClick={() => setIntroDraftOpen(true)}>{t("Draft introduction request", "اكتب طلب المقدمة")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</button><Link href="/requests/new" className="text-link">{t("Write a public request instead", "اكتب طلبا عاما بدلا من ذلك")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</Link><p className="form-hint">{t("Free tier: 1 introduction request. Member: unlimited.", "الفئة المجانية: طلب مقدمة واحد. العضو: غير محدود.")}</p></>}</>) : <><Link href="/signup" className="button button-primary">{t("Join to request an introduction", "انضم لطلب مقدمة")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</Link><p className="member-access-note"><span className="mono">{t("Visitor access", "وصول الزائر")}</span> {t("Profile context is open; introductions and direct contact are available to members.", "سياق الملف مفتوح؛ المقدمات والتواصل المباشر متاحان للأعضاء.")}</p></>}</aside></div>;
  return workspace ? <ProductShell title={t("Member profile", "ملف العضو")} active="/dashboard/discussions"><div className="workspace-route-page"><div className="product-page-heading compact"><div><SectionLabel>{t("Workspace / Member profile", "مساحة العمل / ملف العضو")}</SectionLabel><h1>{t("Context before contact.", "السياق قبل التواصل.")}</h1><p>{t("Review why this person surfaced, their experience, and the right way to make a focused introduction.", "راجع سبب ظهور هذا الشخص وخبرته والطريقة المناسبة لبدء مقدمة مركزة.")}</p></div><Link href="/dashboard/discussions" className="button button-light">{t("Back to community", "العودة إلى المجتمع")} <ArrowLeft size={14} /></Link></div>{body}</div></ProductShell> : <><section className="public-member-profile-hero"><div className="container public-member-profile-hero__inner"><div><SectionLabel>{t("Connect / Member evidence", "تواصل / دليل العضو")}</SectionLabel><h1>{person.name}</h1><p>{t(`${person.role} in ${person.city}. Review the practical context before asking for an introduction.`, `${person.roleAr} في ${person.cityAr}. راجع السياق العملي قبل طلب مقدمة.`)}</p><Link href="/matching" className="button button-primary">{t("Return to matching", "العودة إلى المطابقة")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</Link></div><aside className="public-member-profile-rail"><span className="mono">{t("ROLE / STAGE / INTRODUCTION", "الدور / المرحلة / المقدمة")}</span><ol><li><i>{t("01", "٠١")}</i><div><strong>{t("Role", "الدور")}</strong><small>{t(person.focus, person.focusAr)}</small></div></li><li><i>{t("02", "٠٢")}</i><div><strong>{t("Stage", "المرحلة")}</strong><small>{t(`${person.stage} teams`, `${person.stage === "Scale" ? "توسع" : person.stage === "Build" ? "بناء" : "تحقق"} فرق`)}</small></div></li><li><i>{t("03", "٠٣")}</i><div><strong>{t("Introduction", "المقدمة")}</strong><small>{t("One focused question", "سؤال مركز واحد")}</small></div></li></ol><p>{t("The member’s relevance and the purpose of the introduction stay visible together.", "تظل ملاءمة العضو وهدف المقدمة ظاهرين معا.")}</p></aside></div></section><div className="missing-public public-member-profile"><div className="container">{body}</div></div></>;
}

export function WorkspaceRequestsPage() {
  const { t, formatNum } = useLocale();
  const [active, setActive] = useState("All");
  // ponytail: tabs now filter on the requests' own `status` field instead of a
  // hardcoded array slice, and counts are derived from that same predicate so they
  // can never drift from what's actually on screen.
  const tabs: { label: string; match: (item: (typeof requests)[number]) => boolean }[] = [
    { label: "All", match: () => true },
    { label: "Waiting on me", match: (item) => item.status === "waiting" },
    { label: "Closed", match: (item) => item.status === "closed" },
  ];
  const visible = requests.filter(tabs.find((tab) => tab.label === active)?.match ?? (() => true));
  return <ProductShell title={t("Requests", "الطلبات")} active="/dashboard/requests"><div className="workspace-route-page"><div className="product-page-heading compact"><div><SectionLabel>{t("Workspace / My requests", "مساحة العمل / طلباتي")}</SectionLabel><h1>{t("Keep every ask moving toward an answer.", "أبقِ كل طلب متجها نحو إجابة.")}</h1><p>{t("See the requests you wrote, the responses you sent, and the context still waiting on you.", "راجع الطلبات التي كتبتها والردود التي أرسلتها والسياق الذي ما زال ينتظر منك خطوة.")}</p></div><Link href="/requests/new" className="button button-primary">{t("Write a request", "اكتب طلبا")} <ArrowRight size={14} /></Link></div><RelationshipThread labels={[t("Ask", "الطلب"), t("Context", "السياق"), t("Reply", "الرد")]} ariaLabel={t("How a request moves toward an answer", "كيف يتحرك الطلب نحو إجابة")} /><div className="workspace-status-tabs" role="tablist" aria-label={t("Request status", "حالة الطلب")}>{tabs.map((tab) => <button type="button" role="tab" aria-selected={active === tab.label} className={active === tab.label ? "active" : ""} key={tab.label} onClick={() => setActive(tab.label)}>{t(tab.label, tab.label === "Waiting on me" ? "بانتظاري" : tab.label === "Closed" ? "مغلق" : "الكل")} <small>{formatNum(requests.filter(tab.match).length)}</small></button>)}</div><div className="workspace-request-list">{visible.map((item, index) => <Link href={`/dashboard/requests/${index + 1}`} className="workspace-request-row" key={item.title}><div className="request-index">{formatNum(`0${index + 1}`)}</div><div><SignalTag tone="soft">{item.type}</SignalTag><h2>{t(item.title, item.titleAr)}</h2><p>{t(item.meta, item.metaAr)}</p></div><span className={item.status === "waiting" ? "status-pill active" : "status-pill"}>{item.status === "waiting" ? t("Needs reply", "يحتاج ردا") : t("Open", "مفتوح")}</span><ArrowRight size={16} aria-hidden="true" /></Link>)}</div></div></ProductShell>;
}

