export function RegistrationsPage() {
  const { t, formatNum } = useLocale();
  const [records, setRecords] = useState(() => getWorkflowRecords());
  const [filter, setFilter] = useState<"all" | "decision" | "event" | "application">("all");
  const [followUps, setFollowUps] = useState<Record<string, boolean>>(() => {
    if (typeof window === "undefined") return {};
    try { return JSON.parse(window.localStorage.getItem("asaasi-event-follow-ups") ?? "{}"); } catch { return {}; }
  });
  const [reviewed, setReviewed] = useState<Record<string, boolean>>(() => {
    if (typeof window === "undefined") return {};
    try { return JSON.parse(window.localStorage.getItem("asaasi-workflow-reviewed") ?? "{}"); } catch { return {}; }
  });
  useEffect(() => { window.localStorage.setItem("asaasi-event-follow-ups", JSON.stringify(followUps)); }, [followUps]);
  useEffect(() => { window.localStorage.setItem("asaasi-workflow-reviewed", JSON.stringify(reviewed)); }, [reviewed]);
  const shown = filter === "all" ? records : records.filter((record) => record.kind === filter);
  const openRecords = records.filter((record) => !reviewed[record.id]);
  const nextRecord = openRecords.find((record) => record.kind === "application") ?? openRecords.find((record) => record.kind === "event" && !followUps[record.id]) ?? openRecords[0];
  const clear = (id: string) => { removeWorkflowRecord(id); setRecords(getWorkflowRecords()); setReviewed((current) => { const { [id]: _, ...rest } = current; return rest; }); };
  const labels = { all: t("All activity", "كل النشاط"), decision: t("Saved work", "العمل المحفوظ"), event: t("Events", "الفعاليات"), application: t("Applications", "الطلبات") };
  return <ProductShell title={t("Activity", "النشاط")} active="/dashboard/registrations"><div className="workspace-route-page"><div className="product-page-heading compact"><div><SectionLabel>{t("Workspace / Activity", "مساحة العمل / النشاط")}</SectionLabel><h1>{t("Keep the work you chose visible.", "أبقِ العمل الذي اخترته ظاهرا.")}</h1><p>{t("Saved decisions, event follow-ups, and submitted applications stay together so you can return with the context intact.", "تبقى القرارات المحفوظة ومتابعات الفعاليات والطلبات المقدمة معا لتعود والسياق محفوظ.")}</p></div><SignalTag tone="soft">{t(`${formatNum(records.length)} records`, `${formatNum(records.length)} سجلات`)}</SignalTag></div>{nextRecord && <section className="activity-review-panel" aria-labelledby="activity-review-title"><div><SectionLabel>{t("Activity review / next open loop", "مراجعة النشاط / الحلقة المفتوحة التالية")}</SectionLabel><h2 id="activity-review-title">{t(nextRecord.title, nextRecord.titleAr)}</h2><p>{nextRecord.kind === "application" ? t("Your submitted brief is in review. Keep the route close in case more context is requested.", "موجزك المقدم قيد المراجعة. أبقِ المسار قريبا في حال طلب سياق إضافي.") : nextRecord.kind === "event" ? t("The event is saved. Add the follow-up that will make the room useful after you leave it.", "الفعالية محفوظة. أضف المتابعة التي ستجعل الغرفة مفيدة بعد مغادرتها.") : t("Resume this decision before the next conversation changes its evidence.", "استأنف هذا القرار قبل أن تغيّر المحادثة التالية دليله.")}</p><div className="activity-review-panel__actions"><Link href={nextRecord.href} className="button button-dark">{t("Resume record", "استأنف السجل")} <ArrowRight size={14} /></Link>{nextRecord.kind === "event" && <button type="button" className="button button-light" onClick={() => setFollowUps((current) => ({ ...current, [nextRecord.id]: !current[nextRecord.id] }))}>{followUps[nextRecord.id] ? t("Follow-up set", "تم ضبط المتابعة") : t("Set follow-up", "اضبط المتابعة")}</button>}<button type="button" className="text-link" onClick={() => setReviewed((current) => ({ ...current, [nextRecord.id]: true }))}>{t("Mark reviewed", "علِّم كمراجَع")}</button></div></div><aside><span className="mono">{t("OPEN WORK", "عمل مفتوح")}</span><strong>{formatNum(openRecords.length)}</strong><p>{t(`${formatNum(records.length - openRecords.length)} reviewed`, `${formatNum(records.length - openRecords.length)} تمت مراجعته`)}</p></aside></section>}<div className="request-tabs" role="toolbar" aria-label={t("Filter workspace activity", "تصفية نشاط مساحة العمل")}>{(["all", "decision", "event", "application"] as const).map((kind) => <button type="button" key={kind} className={filter === kind ? "active" : ""} aria-pressed={filter === kind} onClick={() => setFilter(kind)}>{labels[kind]}</button>)}</div>{shown.length ? <div className="receipt-list">{shown.map((record) => <article key={record.id} className={reviewed[record.id] ? "is-reviewed" : ""}><div><span className="mono">{reviewed[record.id] ? t("REVIEWED", "تمت المراجعة") : t(`${record.kind.toUpperCase()} / ${record.status.toUpperCase()}`, `${record.kind === "decision" ? "قرار" : record.kind === "event" ? "فعالية" : "طلب"} / ${record.status === "submitted" ? "مقدم" : record.status === "registered" ? "محفوظ" : "محفوظ"}`)}</span><h2>{t(record.title, record.titleAr)}</h2><p>{reviewed[record.id] ? t("This record is reviewed. Reopen it whenever a new conversation or commitment changes the work.", "تمت مراجعة هذا السجل. أعد فتحه عندما تغيّر محادثة أو التزام جديد العمل.") : record.kind === "event" ? t("Keep the event close with a calendar handoff or reminder.", "أبقِ الفعالية قريبة عبر إضافة للتقويم أو تذكير.") : record.kind === "application" ? t("Your brief is in review. Return to it if the route asks for more context.", "موجزك قيد المراجعة. عد إليه إذا طلب المسار مزيدا من السياق.") : t("Return to this decision when the next conversation changes the evidence.", "عد إلى هذا القرار عندما تغيّر المحادثة التالية الدليل.")}</p></div><div className="activity-row-actions"><Link href={record.href} className="button button-ghost">{t("Open", "افتح")} <ArrowRight size={14} /></Link>{record.kind === "event" && <button type="button" className="button button-light" aria-pressed={followUps[record.id] ?? false} onClick={() => setFollowUps((current) => ({ ...current, [record.id]: !current[record.id] }))}><CalendarPlus size={14} /> {followUps[record.id] ? t("Follow-up set", "تم ضبط المتابعة") : t("Set follow-up", "اضبط المتابعة")}</button>}<button type="button" className="text-link" onClick={() => setReviewed((current) => ({ ...current, [record.id]: !current[record.id] }))}>{reviewed[record.id] ? t("Reopen", "أعد الفتح") : t("Mark reviewed", "علِّم كمراجَع")}</button><button type="button" className="text-link" onClick={() => clear(record.id)}>{t("Remove", "إزالة")}</button></div></article>)}</div> : <div className="empty-state compact-empty"><h2>{t("Your activity will collect here.", "سيتجمع نشاطك هنا.")}</h2><p>{t("Save a decision, keep an event, or submit an application to create a useful record you can return to.", "احفظ قرارا أو احتفظ بفعالية أو قدم طلبا لإنشاء سجل مفيد تعود إليه.")}</p><Link href="/tools" className="button button-dark">{t("Open founder tools", "افتح أدوات المؤسس")}</Link></div>}</div></ProductShell>;
}

export function OrganizationHubPage() {
  const { t, formatNum } = useLocale();
  return <ProductShell title={t("Organizations", "المنظمات")} active="/dashboard/organizations"><div className="workspace-route-page"><div className="product-page-heading compact"><div><SectionLabel>{t("Workspace / Organizations", "مساحة العمل / المنظمات")}</SectionLabel><h1>{t("Build the workspace your team needs.", "ابنِ مساحة العمل التي يحتاجها فريقك.")}</h1><p>{t("Keep your organization profile, members, requests, and programs connected. Growth subscribers can invite up to 5 teammates into the same workspace.", "أبقِ ملف منظمتك وأعضاءها وطلباتها وبرامجها مترابطة. يمكن لمشتركي خطة النمو دعوة حتى ٥ من أعضاء الفريق إلى نفس مساحة العمل.")}</p></div><Link href="/organizations/new" className="button button-primary">{t("Create organization", "أنشئ منظمة")} <ArrowRight size={14} /></Link></div><div className="organization-cards"><article className="organization-card"><div className="org-avatar">AS</div><div><span className="mono">{t("OWNER", "مالك")}</span><h2>ASaaSI Studio</h2><p>{t(`${3} members · ${2} active requests`, `${formatNum(3)} أعضاء · ${formatNum(2)} طلبات نشطة`)}</p></div><Link href="/organizations/workspace" className="text-link">{t("Open workspace", "افتح مساحة العمل")} <ArrowRight size={14} /></Link></article><article className="organization-card muted"><div className="org-plus">+</div><div><span className="mono">{t("JOIN ANOTHER", "انضم لأخرى")}</span><h2>{t("Have an invitation?", "لديك دعوة؟")}</h2><p>{t("Enter a token and keep the work in one place.", "أدخل رمزا وأبقِ العمل في مكان واحد.")}</p></div><Link href="/organizations/join" className="text-link">{t("Join organization", "انضم لمنظمة")} <ArrowRight size={14} /></Link></article></div></div></ProductShell>;
}

