export function SystemStatePage({ code = "404" }: { code?: string }) {
  const { t } = useLocale();
  const copy: Record<string, { title: string; body: string; titleAr: string; bodyAr: string }> = {
    "403": { title: "This page is not in your orbit yet.", body: "You may need an invitation or a different workspace role to open this route.", titleAr: "هذه الصفحة ليست ضمن دائرتك بعد.", bodyAr: "قد تحتاج إلى دعوة أو دور مختلف في مساحة العمل لفتح هذا المسار." },
    "429": { title: "The network needs a breath.", body: "Too many requests arrived at once. Wait a moment, then try again.", titleAr: "تحتاج الشبكة إلى لحظة هدوء.", bodyAr: "وصلت طلبات كثيرة في الوقت نفسه. انتظر قليلا ثم حاول مرة أخرى." },
    "500": { title: "Something lost the thread.", body: "The route is unavailable right now. Your work has not been changed.", titleAr: "انقطع الخيط مؤقتا.", bodyAr: "المسار غير متاح الآن. لم يتغير أي شيء من عملك." },
    offline: { title: "You are temporarily offline.", body: "Reconnect to continue. We will keep the last useful screen close.", titleAr: "أنت غير متصل مؤقتا.", bodyAr: "أعد الاتصال للمتابعة. سنبقي آخر شاشة مفيدة قريبة منك." },
    maintenance: { title: "We are tuning things up.", body: "ASaaSI is in a short maintenance window. Come back soon.", titleAr: "نضبط بعض الأمور الآن.", bodyAr: "أساسي في نافذة صيانة قصيرة. عد بعد قليل." },
    "invitation-expired": { title: "That invitation has closed.", body: "Ask the organization owner for a new link, or return to your workspace.", titleAr: "انتهت صلاحية هذه الدعوة.", bodyAr: "اطلب رابطا جديدا من مالك المنظمة أو عد إلى مساحة عملك." }
  };
  const fallback = { title: "This route is not on the map yet.", body: "Try a known destination or return to the ASaaSI home.", titleAr: "هذا المسار غير موجود على الخريطة بعد.", bodyAr: "جرب وجهة معروفة أو عد إلى الصفحة الرئيسية لأساسي." };
  const item = copy[code] ?? fallback;
  const recovery = code === "invitation-expired" ? { mark: ["INVITATION / CLOSED", "الدعوة / مغلقة"], first: ["Ask the owner for a fresh link", "اطلب رابطا جديدا من المالك"], second: ["Return to the organization record", "عد إلى سجل المنظمة"] } : code === "offline" ? { mark: ["CONNECTION / PAUSED", "الاتصال / متوقف"], first: ["Reconnect when the signal returns", "أعد الاتصال عند عودة الإشارة"], second: ["Resume from the last useful screen", "استأنف من آخر شاشة مفيدة"] } : { mark: ["ROUTE / HELD", "المسار / متوقف"], first: ["Read the state before changing course", "اقرأ الحالة قبل تغيير المسار"], second: ["Choose the useful recovery route", "اختر مسار الاستعادة المفيد"] };
  return <div className="system-state-page"><div className="system-state-record"><header><div className="system-state-node" aria-hidden="true"><i /><i /><i /></div><div><SectionLabel>{t(`System / ${code}`, `النظام / ${code}`)}</SectionLabel><span className="mono">{t(recovery.mark[0], recovery.mark[1])}</span></div></header><h1>{t(item.title, item.titleAr)}</h1><p>{t(item.body, item.bodyAr)}</p><ol className="system-recovery-path"><li><span>01</span><strong>{t(recovery.first[0], recovery.first[1])}</strong></li><li><span>02</span><strong>{t(recovery.second[0], recovery.second[1])}</strong></li></ol><div className="system-state-actions"><Link href="/" className="button button-primary">{t("Back to ASaaSI", "العودة إلى أساسي")} <ArrowRight size={14} /></Link><Link href={code === "invitation-expired" ? "/organizations/join" : "/support"} className="button button-ghost">{code === "invitation-expired" ? t("Open organization access", "افتح وصول المنظمة") : t("Open support", "فتح الدعم")}</Link></div></div></div>;
}

