export function MembershipHubPage() {
  const { t, formatNum } = useLocale();
  const { message, showToast, clearToast } = useToast();
  const [subscriber] = useState(() => typeof window !== "undefined" && window.localStorage.getItem("asaasi-access-tier") === "subscriber");
  const [redeemed, setRedeemed] = useState<string[]>([]);
  const [joined, setJoined] = useState<string[]>([]);
  const [downloaded, setDownloaded] = useState<string[]>([]);
  const [booked, setBooked] = useState<Record<string, string>>({});
  const [teammates, setTeammates] = useState<string[]>([]);
  const [teammateEmail, setTeammateEmail] = useState("");
  const inviteTeammate = (event: FormEvent) => { event.preventDefault(); if (!teammateEmail.trim() || teammates.length >= 5) return; setTeammates((current) => [...current, teammateEmail.trim()]); setTeammateEmail(""); showToast(t("Invitation sent.", "تم إرسال الدعوة.")); };
  return <ProductShell title={t("Membership perks", "مزايا العضوية")} active="/dashboard/perks"><div className="workspace-route-page">
    <div className="product-page-heading compact"><div><SectionLabel>{t("Workspace / Membership perks", "مساحة العمل / مزايا العضوية")}</SectionLabel><h1>{t("Everything Member access unlocks, in one place.", "كل ما يفتحه وصول العضو، في مكان واحد.")}</h1><p>{t("Vendor discounts, facilitated masterminds, 1:1 mentor time, market reports, and team seats.", "خصومات موردين، ومجموعات مُيسَرة، ووقت مرشد فردي، وتقارير سوقية، ومقاعد فريق.")}</p></div><SignalTag tone={subscriber ? "yellow" : "soft"}>{subscriber ? t("Member active", "العضو نشط") : t("Free Member", "عضو مجاني")}</SignalTag></div>

    <section className="panel-card" style={{ marginBottom: 24 }}><SectionLabel><Gift size={14} style={{ verticalAlign: -2, marginInlineEnd: 6 }} />{t("Perks & Deals", "المزايا والعروض")}</SectionLabel><h2>{t("Vendor discounts worth more than the membership fee.", "خصومات موردين تفوق قيمتها رسم العضوية.")}</h2>{subscriber ? <div className="perk-grid">{perks.map((perk) => <article className="perk-card" key={perk.name}><strong>{perk.name}</strong><span className="mono">{t(perk.offer, perk.offerAr)}</span><p>{t(perk.copy, perk.copyAr)}</p><button type="button" className="button button-primary button-small" disabled={redeemed.includes(perk.name)} onClick={() => { setRedeemed((current) => [...current, perk.name]); showToast(t(`Access request sent for ${perk.name}. We'll verify and follow up by email.`, `أُرسل طلب الوصول إلى ${perk.name}. سنتحقق ونتابع عبر البريد الإلكتروني.`)); }}>{redeemed.includes(perk.name) ? <><Check size={14} /> {t("Requested", "تم الطلب")}</> : t("Request access", "اطلب الوصول")}</button></article>)}</div> : <MemberGate label={t("Perks & Deals", "المزايا والعروض")} />}</section>

    <section className="panel-card" style={{ marginBottom: 24 }}><SectionLabel><Users size={14} style={{ verticalAlign: -2, marginInlineEnd: 6 }} />{t("Masterminds", "المجموعات الإرشادية")}</SectionLabel><h2>{t("Small, facilitated groups matched to your stage.", "مجموعات صغيرة مُيسَرة تُطابق مرحلتك.")}</h2>{subscriber ? <div className="perk-grid">{masterminds.map((group) => <article className="perk-card" key={group.name}><strong>{group.name}</strong><span className="mono">{t(group.cadence, group.cadenceAr)} · {t(group.location, group.locationAr)}</span><p>{t(group.copy, group.copyAr)}</p><button type="button" className="button button-primary button-small" disabled={joined.includes(group.name)} onClick={() => setJoined((current) => [...current, group.name])}>{joined.includes(group.name) ? <><Check size={14} /> {t("Requested", "تم الطلب")}</> : t("Request to join", "اطلب الانضمام")}</button></article>)}</div> : <MemberGate label={t("Masterminds", "المجموعات الإرشادية")} />}</section>

    <section className="panel-card" style={{ marginBottom: 24 }}><SectionLabel><CalendarPlus size={14} style={{ verticalAlign: -2, marginInlineEnd: 6 }} />{t("Mentor matching", "مطابقة المرشدين")}</SectionLabel><h2>{t("Book 1:1 time with an operator who has done it.", "احجز وقتا فرديا مع مشغل خاض التجربة.")}</h2>{subscriber ? <div className="perk-grid">{bookableMentors.map((mentor) => <article className="perk-card" key={mentor.name}><strong>{mentor.name}</strong><span className="mono">{t(mentor.focus, mentor.focusAr)}</span>{booked[mentor.name] ? <p className="inline-success" role="status"><Check size={13} /> {t(`Booked: ${booked[mentor.name]}`, `تم الحجز: ${booked[mentor.name]}`)}</p> : <div className="product-actions compact-actions">{mentor.slots.map((slot, index) => <button type="button" key={slot} className="button button-ghost button-small" onClick={() => setBooked((current) => ({ ...current, [mentor.name]: t(slot, mentor.slotsAr[index]) }))}>{t(slot, mentor.slotsAr[index])}</button>)}</div>}</article>)}</div> : <MemberGate label={t("Mentor matching", "مطابقة المرشدين")} />}</section>

    <section className="panel-card" style={{ marginBottom: 24 }}><SectionLabel>{t("Market reports", "تقارير السوق")}</SectionLabel><h2>{t("Data other founders don't have.", "بيانات لا يملكها مؤسسون آخرون.")}</h2>{subscriber ? <div className="perk-grid">{marketReports.map((report) => <article className="perk-card" key={report.name}><strong>{report.name}</strong><span className="mono">{t(report.teaser, report.teaserAr)}</span><p>{t(report.copy, report.copyAr)}</p><button type="button" className="button button-primary button-small" onClick={() => setDownloaded((current) => [...current, report.name])}>{downloaded.includes(report.name) ? <><Check size={14} /> {t("Downloaded", "تم التنزيل")}</> : <><Download size={14} /> {t("Download full report", "نزل التقرير الكامل")}</>}</button></article>)}</div> : <MemberGate label={t("Market reports", "تقارير السوق")} />}</section>

    <section className="panel-card"><SectionLabel><Mail size={14} style={{ verticalAlign: -2, marginInlineEnd: 6 }} />{t("Team seats", "مقاعد الفريق")}</SectionLabel><h2>{t("Invite up to 5 teammates to your workspace.", "ادعُ حتى ٥ أعضاء من فريقك إلى مساحة عملك.")}</h2>{subscriber ? <><div className="saved-list">{teammates.map((email) => <article className="saved-row" key={email}><span className="saved-node" /><div><span className="mono">{t("Invited", "مدعو")}</span><h2>{email}</h2></div><button type="button" className="button button-ghost" onClick={() => setTeammates((current) => current.filter((item) => item !== email))}><Trash2 size={14} /></button></article>)}</div>{teammates.length < 5 ? <form onSubmit={inviteTeammate} className="two-fields" style={{ marginTop: 14 }}><input type="email" required value={teammateEmail} onChange={(event) => setTeammateEmail(event.target.value)} placeholder={t("teammate@company.com", "teammate@company.com")} /><button type="submit" className="button button-primary">{t("Send invite", "أرسل الدعوة")} <ArrowRight size={14} /></button></form> : <p className="form-hint">{t("All 5 seats used.", "استُخدمت المقاعد الخمسة كلها.")}</p>}<p className="form-hint">{t(`${teammates.length} of 5 seats used.`, `${formatNum(teammates.length)} من ٥ مقاعد مُستخدَمة.`)}</p></> : <MemberGate label={t("Team seats", "مقاعد الفريق")} />}</section>
  </div>{message && <Toast message={message} onClose={clearToast} />}</ProductShell>;
}
